import{_ as t,c as a,o as i,aj as n}from"./chunks/framework.CMWtagCP.js";const m=JSON.parse('{"title":"security","description":"","frontmatter":{"title":"security","hugoSource":"computer-science/security.md","outline":[1,6]},"headers":[],"relativePath":"computer-science/2026-11-17-security.md","filePath":"computer-science/2026-11-17-security.md"}'),r={name:"computer-science/2026-11-17-security.md"};function s(c,e,l,o,p,d){return i(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="security" tabindex="-1">security <a class="header-anchor" href="#security" aria-label="Permalink to “security”">​</a></h1><h2 id="man-in-the-middle-attack-中间人攻击" tabindex="-1">man-in-the-middle attack 中间人攻击 <a class="header-anchor" href="#man-in-the-middle-attack-中间人攻击" aria-label="Permalink to “man-in-the-middle attack 中间人攻击”">​</a></h2><p>SSL Pinning is a technique we use on the client side to avoid a man-in-the-middle attack by validating the server certificates. The developers embed (or pin) a list of trustful certificates in the client application during development and use them to compare against the server certificates during runtime.</p><p>If there is a mismatch between the server and the local copy of certificates, the connection will be disrupted, and no further user data will be sent to that server. This enforcement ensures that user devices communicate only with dedicated, trustful servers.</p><p>SSL Pinning prevents a man-in-the-middle attack, which means an attacker can not intercept the traffic and modify the data. If an attacker can not intercept the traffic, the application automatically prevents many server-side vulnerabilities. Because an attacker can not perform API-level test cases, implementing SSL is very important.</p><h3 id="ssl-pinning" tabindex="-1">SSL pinning <a class="header-anchor" href="#ssl-pinning" aria-label="Permalink to “SSL pinning”">​</a></h3><ul><li>reference <ul><li><a href="https://stackoverflow.com/questions/52862256/charles-proxy-for-mobile-apps-that-use-ssl-pinning" target="_blank" rel="noreferrer">Charles Proxy for Mobile apps that use SSL Pinning</a></li><li><a href="https://www.appknox.com/blog/bypass-ssl-pinning-in-ios-app" target="_blank" rel="noreferrer">8 Ways to Bypass SSL Pinning in iOS</a></li></ul></li></ul>',7)])])}const u=t(r,[["render",s]]);export{m as __pageData,u as default};
